import itertools

def split_at(iterable, pred, maxsplit=-1, keep_separator=False):
    """Yield lists of items from *iterable*, where each list is delimited by
    an item where callable *pred* returns ``True``.

        >>> list(split_at('abcdcba', lambda x: x == 'b'))
        [['a'], ['c', 'd', 'c'], ['a']]

        >>> list(split_at(range(10), lambda n: n % 2 == 1))
        [[0], [2], [4], [6], [8], []]

    At most *maxsplit* splits are done. If *maxsplit* is not specified or -1,
    then there is no limit on the number of splits:

        >>> list(split_at(range(10), lambda n: n % 2 == 1, maxsplit=2))
        [[0], [2], [4, 5, 6, 7, 8, 9]]

    By default, the delimiting items are not included in the output.
    To include them, set *keep_separator* to ``True``.

        >>> list(split_at('abcdcba', lambda x: x == 'b', keep_separator=True))
        [['a'], ['b'], ['c', 'd', 'c'], ['b'], ['a']]

    """
    def isplit(iterable, pred, maxsplit=-1, keep_separator=False):
        it = iter(iterable)
        buffer = []
        count = 0
        for item in it:
            if pred(item):
                if buffer:
                    if keep_separator:
                        yield buffer + [item]
                    else:
                        yield buffer
                    buffer = []
                    if maxsplit != -1 and count >= maxsplit:
                        break
                    count += 1
                else:
                    if keep_separator:
                        yield [item]
            else:
                buffer.append(item)
        if buffer:
            yield buffer

    return list(isplit(iterable, pred, maxsplit, keep_separator))

def chunked(iterable, n, strict=False):
    """Break *iterable* into lists of length *n*:

        >>> list(chunked([1, 2, 3, 4, 5, 6], 3))
        [[1, 2, 3], [4, 5, 6]]

    By the default, the last yielded list will have fewer than *n* elements
    if the length of *iterable* is not divisible by *n*:

        >>> list(chunked([1, 2, 3, 4, 5, 6, 7, 8], 3))
        [[1, 2, 3], [4, 5, 6], [7, 8]]

    To use a fill-in value instead, see the :func:`grouper` recipe.

    If the length of *iterable* is not divisible by *n* and *strict* is
    ``True``, then ``ValueError`` will be raised before the last
    list is yielded.

    """
    it = iter(iterable)
    if strict:
        def inner():
            while True:
                chunk = list(islice(it, n))
                if len(chunk) != n:
                    raise ValueError("Iterable is not divisible by n")
                yield chunk
        return inner()
    else:
        return iter(lambda: list(islice(it, n)), [])

from collections.abc import Iterable

def tail(n, iterable):
    """Return an iterator over the last *n* items of *iterable*.

    >>> t = tail(3, 'ABCDEFG')
    >>> list(t)
    ['E', 'F', 'G']

    """
    if not isinstance(iterable, Iterable):
        raise TypeError('Expected an iterable')
    if n < 0:
        raise ValueError('n must be non-negative')
    buffer = []
    for item in iterable:
        buffer.append(item)
        if len(buffer) > n:
            buffer.pop(0)
    return iter(buffer)

def flatten(list_of_lists):
    """Return an iterator flattening one level of nesting in a list of lists.

        >>> list(flatten([[0, 1], [2, 3]]))
        [0, 1, 2, 3]

    See also :func:`collapse`, which can flatten multiple levels of nesting.

    """
    for sublist in list_of_lists:
        for item in sublist:
            yield item

import itertools

def duplicates_justseen(iterable, key=None):
    """Yields serially-duplicate elements after their first appearance.

    >>> list(duplicates_justseen('mississippi'))
    ['s', 's', 'p']
    >>> list(duplicates_justseen('AaaBbbCccAaa', str.lower))
    ['a', 'a', 'b', 'b', 'c', 'c', 'a', 'a']

    This function is analogous to :func:`unique_justseen`.

    """
    def _keyfunc(x):
        return x if key is None else key(x)

    prev = None
    for item in iterable:
        if _keyfunc(item) == _keyfunc(prev):
            yield item
        prev = item

from typing import Iterable

def longest_common_prefix(iterables: Iterable[str]) -> Iterable[str]:
    """Yield elements of the longest common prefix among given *iterables*.

    >>> ''.join(longest_common_prefix(['abcd', 'abc', 'abf']))
    'ab'

    """
    min_length = min(len(iterable) for iterable in iterables)
    for i in range(min_length):
        if all(iterable[i] == iterables[0][i] for iterable in iterables):
            yield iterables[0][i]
        else:
            break

def transpose(matrix):
    """Swap the rows and columns of the input matrix.

    >>> list(transpose([(1, 2, 3), (11, 22, 33)]))
    [(1, 11), (2, 22), (3, 33)]

    The caller should ensure that the dimensions of the input are compatible.
    If the input is empty, no output will be produced.
    """
    if not matrix:
        return []
    return list(map(list, zip(*matrix)))

