def triplewise(iterable):
    """Return overlapping triplets from *iterable*.

    >>> list(triplewise('ABCDE'))
    [('A', 'B', 'C'), ('B', 'C', 'D'), ('C', 'D', 'E')]

    """
    from itertools import islice, tee

    def triplet(iterable):
        a, b, c = tee(iterable, 3)
        next(islice(b, 1, 1), None)
        next(islice(c, 2, 2), None)
        return zip(a, b, c)

    return list(triplet(iterable))

from typing import Iterable, Iterator

def longest_common_prefix(iterables: Iterable[Iterable[str]]) -> Iterator[str]:
    """Yield elements of the longest common prefix among given *iterables*.

    >>> ''.join(longest_common_prefix(['abcd', 'abc', 'abf']))
    'ab'

    """
    if not iterables:
        return

    iterators = [iter(it) for it in iterables]
    try:
        while True:
            current_chars = next(it) for it in iterators
            if len(set(current_chars)) != 1:
                break
            yield current_chars[0]
    except StopIteration:
        pass

