from itertools import islice, tee, chain

def duplicates_justseen(iterable, key=None):
    """Yields serially-duplicate elements after their first appearance.

    >>> list(duplicates_justseen('mississippi'))
    ['s', 's', 'p']
    >>> list(duplicates_justseen('AaaBbbCccAaa', str.lower))
    ['a', 'a', 'b', 'b', 'c', 'c', 'a', 'a']

    This function is analogous to :func:`unique_justseen`.

    """
    def pairwise(iterable):
        a, b = tee(iterable)
        next(b, None)
        return zip(a, b)

    iterable = map(key, iterable) if key else iterable
    last, dupes = None, []
    for item in iterable:
        if item == last:
            dupes.append(item)
        else:
            if dupes:
                yield from dupes
                dupes = []
        last = item
    if dupes:
        yield from dupes

def triplewise(iterable):
    """Return overlapping triplets from *iterable*.

    >>> list(triplewise('ABCDE'))
    [('A', 'B', 'C'), ('B', 'C', 'D'), ('C', 'D', 'E')]

    """
    from itertools import islice, tee

    def triplet(iterable):
        a, b, c = tee(iterable, 3)
        next(b, None)
        next(c, None)
        next(c, None)
        return zip(a, b, c)

    return list(triplet(iterable))

def longest_common_prefix(iterables):
    """Yield elements of the longest common prefix among given *iterables*.

    >>> ''.join(longest_common_prefix(['abcd', 'abc', 'abf']))
    'ab'

    """
    from itertools import islice, tee

    def all_equal(iterable):
        a, b = tee(iterable)
        return all(x == y for x, y in zip(a, islice(b, 1, None)))

    for prefix in zip(*iterables):
        if all_equal(prefix):
            yield prefix[0]
        else:
            break

